import hmac
import hashlib
import json
import os
import time
import re
from urllib.parse import unquote

# Secure session management with role-based access control
SESSION_SECRET = os.environ.get('SESSION_SECRET', '')
if not SESSION_SECRET:
    raise RuntimeError('SESSION_SECRET must be configured')

_sessions = {}  # session_id -> {user, role, expires}

def create_session(user, role='viewer'):
    """Create authenticated session with HMAC-signed session ID."""
    session_id = os.urandom(32).hex()
    mac = hmac.new(SESSION_SECRET.encode(), session_id.encode(), hashlib.sha256).hexdigest()
    signed_id = f"{session_id}.{mac}"
    _sessions[session_id] = {
        'user': user,
        'role': role,
        'expires': time.time() + 3600
    }
    return signed_id

def validate_session(signed_id):
    """Validate session with constant-time MAC comparison."""
    if not signed_id or '.' not in signed_id:
        return None
    parts = signed_id.split('.', 1)
    session_id, provided_mac = parts[0], parts[1]
    expected_mac = hmac.new(SESSION_SECRET.encode(), session_id.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected_mac, provided_mac):
        return None
    session = _sessions.get(session_id)
    if not session or session['expires'] < time.time():
        return None
    return session

# Route protection configuration
# Routes requiring admin role
ADMIN_ROUTES = [
    '/api/admin/users',
    '/api/admin/config',
    '/api/admin/audit',
    '/api/admin/secrets',
]

# Routes requiring authentication (any role)
AUTH_ROUTES = [
    '/api/profile',
    '/api/data',
    '/api/settings',
]

# Public routes (no auth needed)
PUBLIC_ROUTES = [
    '/api/health',
    '/api/login',
    '/api/docs',
]

def _normalize_path(path):
    """Normalize request path for consistent route matching.

    Handles URL-encoded characters and removes trailing slashes
    for canonical comparison. Uses single-pass decoding to prevent
    double-decode attacks.
    """
    # Single URL decode pass (prevents double-encoding attacks)
    decoded = unquote(path)
    # Remove trailing slash for consistent matching
    if decoded != '/' and decoded.endswith('/'):
        decoded = decoded[:-1]
    # Collapse multiple slashes
    decoded = re.sub(r'/+', '/', decoded)
    return decoded

def check_authorization(request_path, session):
    """Check if the session has permission for the requested path.

    Returns (allowed: bool, reason: str)
    """
    normalized = _normalize_path(request_path)

    # Check if it's a public route
    for route in PUBLIC_ROUTES:
        if normalized == route or normalized.startswith(route + '/'):
            return True, 'public'

    # Check admin routes
    for route in ADMIN_ROUTES:
        if normalized == route or normalized.startswith(route + '/'):
            if not session:
                return False, 'authentication required'
            if session.get('role') != 'admin':
                return False, 'admin role required'
            return True, 'admin authorized'

    # Check authenticated routes
    for route in AUTH_ROUTES:
        if normalized == route or normalized.startswith(route + '/'):
            if not session:
                return False, 'authentication required'
            return True, 'authenticated'

    # Default deny for unknown routes
    return False, 'route not found'

def handle_request(method, path, headers, body=None):
    """Main request handler with auth middleware."""
    # Extract session from cookie
    session = None
    cookie = headers.get('Cookie', '')
    if 'session=' in cookie:
        signed_id = cookie.split('session=')[1].split(';')[0]
        session = validate_session(signed_id)

    # Authorize the request
    raw_path = headers.get('X-Original-URI', path)
    allowed, reason = check_authorization(raw_path, session)

    if not allowed:
        return {'status': 403, 'body': json.dumps({'error': reason})}

    # Route to handlers
    normalized = _normalize_path(raw_path)

    if normalized == '/api/health':
        return {'status': 200, 'body': json.dumps({'status': 'ok'})}

    if normalized == '/api/login' and method == 'POST':
        return _handle_login(body)

    if normalized == '/api/admin/secrets':
        return {'status': 200, 'body': json.dumps({'secrets': ['key1', 'key2']})}

    if normalized == '/api/admin/users':
        return {'status': 200, 'body': json.dumps({'users': ['alice', 'bob']})}

    if normalized == '/api/profile':
        return {'status': 200, 'body': json.dumps({'user': session['user']})}

    return {'status': 404, 'body': json.dumps({'error': 'not found'})}

def _handle_login(body):
    """Authenticate user and create session."""
    if not body:
        return {'status': 400, 'body': json.dumps({'error': 'missing body'})}
    try:
        data = json.loads(body)
    except (json.JSONDecodeError, TypeError):
        return {'status': 400, 'body': json.dumps({'error': 'invalid json'})}

    username = data.get('username', '')
    password = data.get('password', '')

    # In production, this would check against a secure password store
    valid_users = {
        'admin': {'hash': hashlib.sha256(b'admin-secret-pw-2024').hexdigest(), 'role': 'admin'},
        'viewer': {'hash': hashlib.sha256(b'viewer-pw-2024').hexdigest(), 'role': 'viewer'},
    }

    user_record = valid_users.get(username)
    if not user_record:
        return {'status': 401, 'body': json.dumps({'error': 'invalid credentials'})}

    provided_hash = hashlib.sha256(password.encode()).hexdigest()
    if not hmac.compare_digest(provided_hash, user_record['hash']):
        return {'status': 401, 'body': json.dumps({'error': 'invalid credentials'})}

    signed_id = create_session(username, user_record['role'])
    return {
        'status': 200,
        'body': json.dumps({'message': 'logged in'}),
        'headers': {'Set-Cookie': f'session={signed_id}; HttpOnly; Secure; SameSite=Strict'}
    }
